const pairs = $node['DexScreener API'].json.pairs || [];
const coingecko = $node['CoinGecko API'].json || [];
const data = [];
const mockDiscussions = [
  {
    source: 'Insyder Crypto',
    content: 'Traded PEPE at $0.01, SHIB trending in memecoin market. Discussed DeFi pumps.',
    id: 'mock1'
  },
  {
    source: 'leensx100',
    content: 'Bought Solana at $150, sold at $180. ZombieCoin trending on DEX. Bullish market.',
    id: 'mock2'
  }
];
mockDiscussions.forEach(d => {
  const coins = [];
  const coinNames = [...pairs.map(p => p.baseToken.name.toLowerCase()), ...coingecko.map(cg => cg.name.toLowerCase())];
  coinNames.forEach(name => {
    if (d.content.toLowerCase().includes(name) && d.content.match(/trade|buy|sell|trending|market|up|down/i)) {
      coins.push({ name, context: d.content.match(/trade|buy|sell|trending|market|up|down/i)[0] });
    }
  });
  const topics = d.content.match(/memecoin|defi|solana|market|trends|trading|bullish/i) ? d.content.match(/memecoin|defi|solana|market|trends|trading|bullish/i).join(', ') : 'General crypto discussion';
  const summary = `${d.source} discussion ${d.id} covered ${topics}. Coins: ${coins.map(c => `${c.name} (${c.context})`).join(', ') || 'None'}.`;
  data.push({ source: d.source, id: d.id, coins, topics, summary });
});
return data.map(d => ({ json: d }));

const pairs = $node['DexScreener API'].json.pairs || [];
const coingecko = $node['CoinGecko API'].json || [];
const data = [];
if (!pairs.length && !coingecko.length) {
  return [{ json: { error: 'No token data' } }];
}
pairs.forEach(pair => {
  const token = pair.baseToken;
  const cgToken = coingecko.find(cg => cg.name.toLowerCase() === token.name.toLowerCase() || cg.symbol.toLowerCase() === token.symbol.toLowerCase()) || {};
  const sentiment = {
    twitter: 0,
    telegram: 0,
    news: 0
  };
  const content_type = 'none';
  const potential_score = Math.random() * 0.5 + 0.5;
  const risk_score = Math.random() * 0.4 + 0.6;
  if (risk_score > 0.7) {
    data.push({
      name: token.name,
      address: token.address,
      narrative: pair.info?.description || 'Generic Meme',
      website: cgToken.homepage?.[0] || 'N/A',
      twitter_handle: cgToken.twitter_screen_name || 'N/A',
      twitter_content_type: content_type,
      market_cap_range: cgToken.market_cap ? `${cgToken.low_24h?.usd || 0}-${cgToken.high_24h?.usd || 0} USD` : 'N/A',
      potential_score,
      risk_score,
      sentiment
    });
  }
});
return data.map(d => ({ json: d }));

const tokens = $node['Score Tokens'].json;
const marketAnalysis = $node['Mock Market Analysis'].json || [];
const successfulCoins = ['DOGE', 'SHIB', 'PEPE', 'BONK', 'FLOKI'];
const themes = ['Animal Kingdom', 'Meme Legends'];
const data = [];
if (!tokens.name) {
  return [{ json: { error: 'No token data' } }];
}
const marketSummary = marketAnalysis.length ? marketAnalysis.map(s => s.summary).join(' ') : 'No recent market insights.';
successfulCoins.forEach(coin => {
  const ticker = `W${coin.slice(0, 3).toUpperCase()}`;
  data.push({
    name: `Wrapped${coin}`,
    ticker: ticker.length <= 5 ? ticker : coin.slice(0, 4).toUpperCase(),
    narrative: `Wrapped ${coin} for DeFi in ${themes[0]}, inspired by: ${marketSummary.slice(0, 50)}...`,
    content_ideas: [
      `🚀 ${ticker} is here! Stake for ${themes[0]} rewards! #memecoin`,
      `Join ${coin} in ${themes[0]} with ${ticker}! #${coin}`
    ]
  });
});
data.push({
  name: `Meme${tokens.name}`,
  ticker: tokens.name.slice(0, 4).toUpperCase(),
  narrative: `${tokens.narrative} in ${themes[1]}, inspired by: ${marketSummary.slice(0, 50)}...`,
  content_ideas: [
    `🌟 ${tokens.name} is live! ${themes[1]} vibes! #memecoin`,
    `Hop on ${tokens.name}! #${tokens.narrative.replace(' ', '')}`
  ]
});
return data.map(d => ({ json: d }));
